 889           Escape = optimizeEarlyExitInductionUser(Plan, TypeInfo, PredVPBB,
 890                                                   ExitIRI->getOperand(Idx));
 891         if (Escape)
 892           ExitIRI->setOperand(Idx, Escape);
 893       }
 894     }
 895   }
