1110   case Instruction::Or:
1111   case Instruction::Freeze:
1112     // TODO: Cover additional opcodes.
1113     return vputils::onlyFirstLaneUsed(this);
1114   case VPInstruction::ActiveLaneMask:
1115   case VPInstruction::ExplicitVectorLength:
1116   case VPInstruction::CalculateTripCountMinusVF:
1117   case VPInstruction::CanonicalIVIncrementForPart:
1118   case VPInstruction::BranchOnCount:
1119   case VPInstruction::BranchOnCond:
1120   case VPInstruction::Broadcast:
1121   case VPInstruction::ReductionStartVector:
1122     return true;
1123   case VPInstruction::PtrAdd:
1124     return Op == getOperand(0) || vputils::onlyFirstLaneUsed(this);
1125   case VPInstruction::ComputeAnyOfResult:
1126   case VPInstruction::ComputeFindIVResult:
1127     return Op == getOperand(1);
1128   case VPInstruction::ExtractLane:
1129     return Op == getOperand(0);
1130   };
1131   llvm_unreachable("switch should return");
1132 }
