1134 bool VPInstruction::onlyFirstPartUsed(const VPValue *Op) const {
1135   assert(is_contained(operands(), Op) && "Op must be an operand of the recipe");
1136   if (Instruction::isBinaryOp(getOpcode()))
1137     return vputils::onlyFirstPartUsed(this);
1138 
1139   switch (getOpcode()) {
1140   default:
1141     return false;
1142   case Instruction::FCmp:
1143   case Instruction::ICmp:
1144   case Instruction::Select:
1145     return vputils::onlyFirstPartUsed(this);
1146   case VPInstruction::BranchOnCount:
1147   case VPInstruction::BranchOnCond:
1148   case VPInstruction::CanonicalIVIncrementForPart:
1149     return true;
1150   };
1151   llvm_unreachable("switch should return");
1152 }
